"""Search API resource."""

from __future__ import annotations

import re
from datetime import date

from tinyfish._utils.resource import BaseAsyncAPIResource, BaseSyncAPIResource

from .types import SearchQueryResponse

SEARCH_RECENCY_MINUTES_MAX = 5_256_000
SEARCH_PURPOSE_MAX_LENGTH = 2000
ISO_DATE_PATTERN = re.compile(r"^\d{4}-\d{2}-\d{2}$")


def _validate_iso_date(field_name: str, value: str) -> str:
    if not ISO_DATE_PATTERN.fullmatch(value):
        raise ValueError(f"{field_name} must be YYYY-MM-DD")

    try:
        date.fromisoformat(value)
    except ValueError as exc:
        raise ValueError(f"{field_name} must be YYYY-MM-DD") from exc

    return value


def _validate_pub_year(field_name: str, value: int) -> None:
    if not isinstance(value, int) or isinstance(value, bool):
        raise ValueError(f"{field_name} must be an integer")
    if not 0 <= value <= 9999:
        raise ValueError(f"{field_name} must be between 0 and 9999")


def _build_search_params(
    *,
    query: str,
    purpose: str | None = None,
    location: str | None = None,
    language: str | None = None,
    include_domains: str | None = None,
    exclude_domains: str | None = None,
    after_date: str | None = None,
    before_date: str | None = None,
    recency_minutes: int | None = None,
    domain_type: str | None = None,
    pub_year_min: int | None = None,
    pub_year_max: int | None = None,
    page: int | None = None,
) -> dict[str, str]:
    if not query or not query.strip():
        raise ValueError("query must be a non-empty string")
    if purpose is not None:
        if not purpose.strip():
            raise ValueError("purpose must be a non-empty string")
        if len(purpose) > SEARCH_PURPOSE_MAX_LENGTH:
            raise ValueError(f"purpose must be at most {SEARCH_PURPOSE_MAX_LENGTH} characters")
    if page is not None:
        if not isinstance(page, int) or isinstance(page, bool):
            raise ValueError("page must be an integer")
        if not 0 <= page <= 10:
            raise ValueError("page must be between 0 and 10")
    if recency_minutes is not None:
        if not isinstance(recency_minutes, int) or isinstance(recency_minutes, bool):
            raise ValueError("recency_minutes must be an integer")
        if recency_minutes < 1:
            raise ValueError("recency_minutes must be >= 1")
        if recency_minutes > SEARCH_RECENCY_MINUTES_MAX:
            raise ValueError(f"recency_minutes must be <= {SEARCH_RECENCY_MINUTES_MAX}")
    if domain_type is not None and domain_type not in ("web", "news", "research_paper"):
        raise ValueError("domain_type must be one of: web, news, research_paper")
    if after_date is not None:
        after_date = _validate_iso_date("after_date", after_date)
    if before_date is not None:
        before_date = _validate_iso_date("before_date", before_date)
    if recency_minutes is not None and (after_date is not None or before_date is not None):
        raise ValueError("recency_minutes cannot be combined with after_date or before_date")
    if after_date is not None and before_date is not None and after_date > before_date:
        raise ValueError("after_date must be on or before before_date")
    if pub_year_min is not None:
        _validate_pub_year("pub_year_min", pub_year_min)
    if pub_year_max is not None:
        _validate_pub_year("pub_year_max", pub_year_max)
    if pub_year_min is not None and pub_year_max is not None and pub_year_min > pub_year_max:
        raise ValueError("pub_year_min must be less than or equal to pub_year_max")

    params: dict[str, str] = {"query": query}
    if purpose is not None:
        params["purpose"] = purpose
    if location is not None:
        params["location"] = location
    if language is not None:
        params["language"] = language
    if include_domains is not None:
        params["include_domains"] = include_domains
    if exclude_domains is not None:
        params["exclude_domains"] = exclude_domains
    if after_date is not None:
        params["after_date"] = after_date
    if before_date is not None:
        params["before_date"] = before_date
    if recency_minutes is not None:
        params["recency_minutes"] = str(recency_minutes)
    if domain_type is not None:
        params["domain_type"] = domain_type
    # browser-search requires a 4-character year string, so zero-pad (e.g. 500 -> "0500").
    if pub_year_min is not None:
        params["pub_year_min"] = f"{pub_year_min:04d}"
    if pub_year_max is not None:
        params["pub_year_max"] = f"{pub_year_max:04d}"
    if page is not None:
        params["page"] = str(page)
    return params


class SearchResource(BaseSyncAPIResource):
    """Search the web using TinyFish's search API."""

    def query(
        self,
        query: str,
        *,
        purpose: str | None = None,
        location: str | None = None,
        language: str | None = None,
        include_domains: str | None = None,
        exclude_domains: str | None = None,
        after_date: str | None = None,
        before_date: str | None = None,
        recency_minutes: int | None = None,
        domain_type: str | None = None,
        pub_year_min: int | None = None,
        pub_year_max: int | None = None,
        page: int | None = None,
    ) -> SearchQueryResponse:
        """Execute a web search query.

        Args:
            query: The search query string.
            purpose: Optional short statement of why you are searching — the
                goal or task the results will be used for. Freeform; gives
                the search additional intent signal for better-quality
                results. When supplied it must be non-empty; max 2000
                characters.
            location: Optional location to scope results (e.g. "United States").
            language: Optional language code (e.g. "en").
            include_domains: Optional comma-separated list of domains to restrict
                results to (e.g. "github.com,arxiv.org").
            exclude_domains: Optional comma-separated list of domains to exclude
                from results (e.g. "pinterest.com,quora.com").
            after_date: Optional date cutoff in YYYY-MM-DD format.
            before_date: Optional date cutoff in YYYY-MM-DD format.
            recency_minutes: Optional rolling freshness window in minutes (1 to 5256000).
            domain_type: Optional search type — "web" (default), "news", or "research_paper".
            pub_year_min: Optional minimum publication year, inclusive (0 to 9999). Only
                supported for domain_type="research_paper".
            pub_year_max: Optional maximum publication year, inclusive (0 to 9999). Only
                supported for domain_type="research_paper".
            page: Result page for pagination.

        Returns:
            SearchQueryResponse with query echo, results list, and total count.

        Raises:
            ValueError: query is empty or whitespace, or purpose is empty or
                over 2000 characters.
            AuthenticationError: Invalid API key.
            RateLimitError: Too many requests.
        """
        params = _build_search_params(
            query=query,
            purpose=purpose,
            location=location,
            language=language,
            include_domains=include_domains,
            exclude_domains=exclude_domains,
            after_date=after_date,
            before_date=before_date,
            recency_minutes=recency_minutes,
            domain_type=domain_type,
            pub_year_min=pub_year_min,
            pub_year_max=pub_year_max,
            page=page,
        )
        return self._get(self._client.product_url("search"), params=params, cast_to=SearchQueryResponse)


class AsyncSearchResource(BaseAsyncAPIResource):
    """Async search the web using TinyFish's search API."""

    async def query(
        self,
        query: str,
        *,
        purpose: str | None = None,
        location: str | None = None,
        language: str | None = None,
        include_domains: str | None = None,
        exclude_domains: str | None = None,
        after_date: str | None = None,
        before_date: str | None = None,
        recency_minutes: int | None = None,
        domain_type: str | None = None,
        pub_year_min: int | None = None,
        pub_year_max: int | None = None,
        page: int | None = None,
    ) -> SearchQueryResponse:
        """Execute a web search query.

        Async version of `SearchResource.query()`.

        Args:
            query: The search query string.
            purpose: Optional short statement of why you are searching — the
                goal or task the results will be used for. Freeform; gives
                the search additional intent signal for better-quality
                results. When supplied it must be non-empty; max 2000
                characters.
            location: Optional location to scope results (e.g. "United States").
            language: Optional language code (e.g. "en").
            include_domains: Optional comma-separated list of domains to restrict
                results to (e.g. "github.com,arxiv.org").
            exclude_domains: Optional comma-separated list of domains to exclude
                from results (e.g. "pinterest.com,quora.com").
            after_date: Optional date cutoff in YYYY-MM-DD format.
            before_date: Optional date cutoff in YYYY-MM-DD format.
            recency_minutes: Optional rolling freshness window in minutes (1 to 5256000).
            domain_type: Optional search type — "web" (default), "news", or "research_paper".
            pub_year_min: Optional minimum publication year, inclusive (0 to 9999). Only
                supported for domain_type="research_paper".
            pub_year_max: Optional maximum publication year, inclusive (0 to 9999). Only
                supported for domain_type="research_paper".
            page: Result page for pagination.

        Returns:
            SearchQueryResponse with query echo, results list, and total count.

        Raises:
            ValueError: query is empty or whitespace, or purpose is empty or
                over 2000 characters.
            AuthenticationError: Invalid API key.
            RateLimitError: Too many requests.
        """
        params = _build_search_params(
            query=query,
            purpose=purpose,
            location=location,
            language=language,
            include_domains=include_domains,
            exclude_domains=exclude_domains,
            after_date=after_date,
            before_date=before_date,
            recency_minutes=recency_minutes,
            domain_type=domain_type,
            pub_year_min=pub_year_min,
            pub_year_max=pub_year_max,
            page=page,
        )
        return await self._get(self._client.product_url("search"), params=params, cast_to=SearchQueryResponse)
